import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Respuestas instantáneas y funciones con palabras clave","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/instant-answers.md","filePath":"es-ES/user-guide/instant-answers.md","lastUpdated":1788190459000}'),n={name:"es-ES/user-guide/instant-answers.md"};function d(i,e,l,r,c,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="respuestas-instantaneas-y-funciones-con-palabras-clave" tabindex="-1">Respuestas instantáneas y funciones con palabras clave <a class="header-anchor" href="#respuestas-instantaneas-y-funciones-con-palabras-clave" aria-label="Permalink to &quot;Respuestas instantáneas y funciones con palabras clave&quot;">​</a></h1><p>Más allá de la búsqueda de archivos locales, Lertaro incluye un potente conjunto de herramientas de cálculo instantáneo, utilidades del sistema y extensiones de plugins mediante palabras clave. Las respuestas aparecen de inmediato sin esperar a los resultados de búsqueda de archivos.</p><h2 id="_1-respuestas-instantaneas-siempre-activas" tabindex="-1">1. Respuestas instantáneas siempre activas <a class="header-anchor" href="#_1-respuestas-instantaneas-siempre-activas" aria-label="Permalink to &quot;1. Respuestas instantáneas siempre activas&quot;">​</a></h2><p>Estas funciones no requieren ningún prefijo de activación; se ejecutan automáticamente cuando la entrada coincide con sus patrones:</p><h3 id="calculadora-y-conversion-de-base" tabindex="-1">Calculadora y conversión de base <a class="header-anchor" href="#calculadora-y-conversion-de-base" aria-label="Permalink to &quot;Calculadora y conversión de base&quot;">​</a></h3><p>Escribe cualquier expresión aritmética directamente en la barra de búsqueda. Los resultados aparecen en tiempo real. Pulsa <code>Enter</code> para copiar el resultado al portapapeles:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span>
<span class="line"><span>100 * (1 - 0.15)</span></span></code></pre></div><p>Admite conversiones de base numérica habituales:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span>
<span class="line"><span>101010 to bin</span></span></code></pre></div><h3 id="expansion-e-inspeccion-de-variables-de-entorno" tabindex="-1">Expansión e inspección de variables de entorno <a class="header-anchor" href="#expansion-e-inspeccion-de-variables-de-entorno" aria-label="Permalink to &quot;Expansión e inspección de variables de entorno&quot;">​</a></h3><ul><li><strong>Expandir variables</strong>: Escribe <code>%NAME%</code> (p. ej. <code>%PATH%</code>, <code>%APPDATA%</code>) para consultar su valor. Las variables con múltiples rutas como <code>PATH</code> se dividen en listas legibles línea por línea.</li><li><strong>Búsqueda difusa de variables</strong>: Escribe <code>%</code> seguido de una palabra clave (p. ej. <code>%temp</code>) para buscar entre todas las variables de entorno del sistema y de usuario.</li></ul><h3 id="ejecucion-rapida-de-comandos" tabindex="-1">Ejecución rápida de comandos <a class="header-anchor" href="#ejecucion-rapida-de-comandos" aria-label="Permalink to &quot;Ejecución rápida de comandos&quot;">​</a></h3><p>Ejecuta comandos directamente sin abrir una terminal previamente:</p><ul><li><code>#&lt;comando&gt;</code>: Abre el símbolo del sistema y ejecuta el comando <strong>con privilegios de administrador</strong> (p. ej. <code>#sfc /scannow</code> o <code>#net start Lertaro.Service</code>).</li><li><code>$&lt;comando&gt;</code>: Abre el símbolo del sistema y ejecuta el comando con <strong>permisos de usuario estándar</strong> (p. ej. <code>$ping 1.1.1.1</code> o <code>$ipconfig /all</code>).</li></ul><h3 id="apertura-directa-de-urls" tabindex="-1">Apertura directa de URLs <a class="header-anchor" href="#apertura-directa-de-urls" aria-label="Permalink to &quot;Apertura directa de URLs&quot;">​</a></h3><p>Escribe o pega cualquier dirección que comience por <code>http://</code> o <code>https://</code> y pulsa <code>Enter</code> para abrirla de inmediato en tu navegador predeterminado. Cuando no hay resultados y la consulta comienza por un dominio sin protocolo, la ventana de búsqueda rápida completa automáticamente <code>https://</code> y mueve el cursor al final; las entradas que ya incluyen un protocolo no se modifican.</p><h3 id="importar-texto-del-portapapeles-en-la-ventana-de-busqueda-rapida" tabindex="-1">Importar texto del portapapeles en la ventana de búsqueda rápida <a class="header-anchor" href="#importar-texto-del-portapapeles-en-la-ventana-de-busqueda-rapida" aria-label="Permalink to &quot;Importar texto del portapapeles en la ventana de búsqueda rápida&quot;">​</a></h3><p>Al mostrar la ventana de búsqueda rápida sin texto prellenado, importa y selecciona automáticamente el texto no vacío del portapapeles si es distinto del último valor importado por esa ventana. El mismo valor no se importa repetidamente y nunca se sobrescriben las consultas prellenadas desde una URI o al volver desde la ventana de búsqueda completa.</p><h2 id="_2-extensiones-activadas-por-palabra-clave-plugins-integrados" tabindex="-1">2. Extensiones activadas por palabra clave (Plugins integrados) <a class="header-anchor" href="#_2-extensiones-activadas-por-palabra-clave-plugins-integrados" aria-label="Permalink to &quot;2. Extensiones activadas por palabra clave (Plugins integrados)&quot;">​</a></h2><p>Escribe una breve <strong>palabra clave activadora + espacio</strong> seguida de tu consulta para invocar funciones específicas de plugins. Todas las palabras clave se pueden personalizar en <a href="./settings/plugins.html"><strong>Configuración → Plugins</strong></a>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Palabra clave predeterminada</th><th style="text-align:left;">Nombre del plugin</th><th style="text-align:left;">Descripción y caso de uso</th><th style="text-align:left;">Ejemplo de uso</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ps</code></td><td style="text-align:left;"><strong>Gestor de procesos</strong></td><td style="text-align:left;">Busca procesos en ejecución por nombre, PID o título de ventana (con pinyin). Pulsa Enter para finalizar.</td><td style="text-align:left;"><code>ps chrome</code> o <code>ps 1234</code></td></tr><tr><td style="text-align:left;"><code>win</code></td><td style="text-align:left;"><strong>Conmutador de ventanas</strong></td><td style="text-align:left;">Busca y cambia entre ventanas abiertas con capturas en miniatura en segundo plano.</td><td style="text-align:left;"><code>win code</code> o <code>win navegador</code></td></tr><tr><td style="text-align:left;"><code>bm</code></td><td style="text-align:left;"><strong>Datos del navegador</strong></td><td style="text-align:left;">Busca marcadores e historial de Chrome, Edge y Firefox (marcadores e historial activables por separado).</td><td style="text-align:left;"><code>bm github</code></td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;"><strong>Búsqueda en Configuración</strong></td><td style="text-align:left;">Búsqueda difusa en las opciones de Lertaro. Al seleccionar una, salta a la página correspondiente y la resalta.</td><td style="text-align:left;"><code>set atajo</code> o <code>set difuso</code></td></tr><tr><td style="text-align:left;"><code>flow</code></td><td style="text-align:left;"><strong>Puente Flow Launcher</strong></td><td style="text-align:left;">Muestra los plugins cargados de Flow.Launcher y sus palabras clave, aprovechando su ecosistema.</td><td style="text-align:left;"><code>flow</code></td></tr><tr><td style="text-align:left;"><code>cs</code></td><td style="text-align:left;"><strong>Búsqueda de contenido</strong></td><td style="text-align:left;">Busca en el texto de documentos locales indexados y muestra archivos coincidentes con fragmentos.</td><td style="text-align:left;"><code>cs plan del proyecto</code></td></tr></tbody></table><h2 id="_3-motores-de-busqueda-web" tabindex="-1">3. Motores de búsqueda web <a class="header-anchor" href="#_3-motores-de-busqueda-web" aria-label="Permalink to &quot;3. Motores de búsqueda web&quot;">​</a></h2><p>El plugin de Búsqueda web incluye accesos directos para los principales motores. Escribe el prefijo seguido de tu consulta para buscar en el navegador:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Atajo</th><th style="text-align:left;">Motor de búsqueda</th><th style="text-align:left;">Ejemplo</th><th style="text-align:left;">Descripción</th></tr></thead><tbody><tr><td style="text-align:left;"><code>bd</code></td><td style="text-align:left;">Baidu</td><td style="text-align:left;"><code>bd aprendizaje profundo</code></td><td style="text-align:left;">Buscar en Baidu</td></tr><tr><td style="text-align:left;"><code>g</code></td><td style="text-align:left;">Google</td><td style="text-align:left;"><code>g lertaro github</code></td><td style="text-align:left;">Buscar en Google</td></tr><tr><td style="text-align:left;"><code>bing</code></td><td style="text-align:left;">Bing</td><td style="text-align:left;"><code>bing documentacion microsoft</code></td><td style="text-align:left;">Buscar en Bing</td></tr><tr><td style="text-align:left;"><code>gh</code></td><td style="text-align:left;">GitHub</td><td style="text-align:left;"><code>gh Lertaro</code></td><td style="text-align:left;">Buscar directamente en repositorios de GitHub</td></tr><tr><td style="text-align:left;"><code>wiki</code></td><td style="text-align:left;">Wikipedia</td><td style="text-align:left;"><code>wiki mecanica cuantica</code></td><td style="text-align:left;">Consultar artículos de Wikipedia</td></tr><tr><td style="text-align:left;"><code>yt</code></td><td style="text-align:left;">YouTube</td><td style="text-align:left;"><code>yt lofi hip hop</code></td><td style="text-align:left;">Buscar vídeos en YouTube</td></tr></tbody></table><p>Puedes añadir, editar o eliminar motores y plantillas de URL en <strong>Configuración → Plugins → Búsqueda web → Configurar</strong>.</p><h2 id="_4-traduccion-instantanea" tabindex="-1">4. Traducción instantánea <a class="header-anchor" href="#_4-traduccion-instantanea" aria-label="Permalink to &quot;4. Traducción instantánea&quot;">​</a></h2><p>Escribe el activador predeterminado <code>tr</code> seguido del texto para traducirlo automáticamente al idioma de interfaz seleccionado en Lertaro:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr Hello, how are you today?</span></span></code></pre></div><ul><li>Los resultados aparecen de forma asíncrona mientras escribes; pulsa <code>Enter</code> para copiar la traducción.</li><li>Personaliza la palabra clave en <strong>Configuración → Plugins → Traductor → Configurar</strong>.</li></ul><h2 id="_5-filtros-de-archivos" tabindex="-1">5. Filtros de archivos <a class="header-anchor" href="#_5-filtros-de-archivos" aria-label="Permalink to &quot;5. Filtros de archivos&quot;">​</a></h2><p>En <strong>Configuración → Plugins → Filtros de archivos → Configurar</strong>, puedes definir ámbitos de búsqueda aislados para carpetas y extensiones concretas:</p><ul><li><strong>Carpetas supervisadas</strong>: Escanea de forma recursiva directorios de trabajo específicos (p. ej. <code>D:\\Ingenieria\\Planos</code>).</li><li><strong>Reglas de coincidencia</strong>: Especifica patrones como <code>*.dwg;*.dxf</code> o <code>*.pdf;*.docx</code>.</li><li><strong>Palabra clave activadora</strong>: Asigna una palabra clave exclusiva (p. ej. <code>cad</code>) para aislar búsquedas (p. ej. <code>cad plano_pieza</code>).</li></ul><h2 id="_6-comandos-personalizados" tabindex="-1">6. Comandos personalizados <a class="header-anchor" href="#_6-comandos-personalizados" aria-label="Permalink to &quot;6. Comandos personalizados&quot;">​</a></h2><p>En <strong>Configuración → Plugins → Comandos personalizados → Configurar</strong>, convierte scripts complejos, herramientas de consola o aplicaciones en comandos concisos:</p><ul><li><strong>Marcadores de posición de parámetros</strong>: Admite marcadores posicionales <code>%s1</code>, <code>%s2</code>... y captura completa de consulta <code>%s</code>.</li><li><strong>Integración con Navegación rápida</strong>: Marca &quot;Mostrar en Navegación rápida&quot; para fijar el comando en el menú de <a href="./hotkeys.html#3-navegacion-rapida-activadores-de-raton"><strong>Navegación rápida</strong></a>, con rutas de submenú usando <code>/</code> (p. ej. <code>HerramientasDev/ReiniciarServicio</code>).</li></ul>`,35)])])}const b=a(n,[["render",d]]);export{g as __pageData,b as default};
